def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (ignored for comparison)
        version_without_build = version.split('+')[0]

        # Split pre-release
        if '-' in version_without_build:
            main_part, prerelease = version_without_build.split('-', 1)
            has_prerelease = True
            prerelease_identifiers = prerelease.split('.')
        else:
            main_part = version_without_build
            has_prerelease = False
            prerelease_identifiers = []

        # Parse major, minor, patch
        parts = main_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, has_prerelease, prerelease_identifiers)

    def prerelease_key(identifiers):
        # Convert prerelease identifiers to sortable form
        result = []
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers: (0, numeric_value)
                result.append((0, int(identifier)))
            else:
                # Non-digit identifiers: (1, string_value)
                result.append((1, identifier))
        return result

    def compare_key(version):
        major, minor, patch, has_prerelease, prerelease_identifiers = parse_version(version)
        # If no prerelease, it comes after prerelease (so use (1,))
        # If prerelease exists, it comes before (so use (0, ...))
        if has_prerelease:
            return (major, minor, patch, 0, prerelease_key(prerelease_identifiers))
        else:
            return (major, minor, patch, 1)

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

